const v = Number(msg.payload);
if (Number.isNaN(v)) {
    return null;
}
msg.payload = v;
return msg;

let state = flow.get('dashboard_state') || { latest_temperature: null, latest_status: 'Aguardando dados', latest_topic: '', last_updated: null, last_command: 'OFF', message_count: 0, history: [] };
state.message_count = (state.message_count || 0) + 1;
state.latest_topic = msg.topic || state.latest_topic;
state.last_updated = (new Date()).toISOString();
if ((msg.topic || '').endsWith('temperatura')) {
    const t = Number(msg.payload);
    if (!Number.isNaN(t)) {
        state.latest_temperature = t;
        state.latest_status = t > 8 ? 'ALERTA' : 'NORMAL';
        state.history = state.history || [];
        state.history.push({ timestamp: state.last_updated, temperature: state.latest_temperature });
        if (state.history.length > 30) state.history.shift();
    } else {
        state.latest_status = 'Dado inválido';
    }
} else if ((msg.topic || '').endsWith('status')) {
    const status = String(msg.payload || '').toUpperCase();
    if (status && status !== 'PING_OK') {
        state.latest_status = status;
    }
} else if ((msg.topic || '').endsWith('comando')) {
    state.last_command = String(msg.payload).toUpperCase() || state.last_command;
}
flow.set('dashboard_state', state);
const currentTemperature = state.latest_temperature === null ? '-- °C' : (Number(state.latest_temperature).toFixed(1) + ' °C');
const m1 = { payload: currentTemperature };
const m2 = { payload: state.latest_status || '--' };
return [m1, m2];

let state = flow.get('dashboard_state') || { mqtt_connected:false, mqtt_message:'Aguardando conexão', mqtt_source:'', latest_temperature:null, latest_status:'Aguardando dados', latest_topic:'', last_updated:null, last_command:'OFF', message_count:0, peak_temperature:null, peak_timestamp:null, history:[] };
msg.headers = { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' };
msg.payload = { success: true, data: state };
return msg;

let body = msg.payload;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch(e) { body = {}; } }
const cmd = (body && body.command || '').toString().trim().toUpperCase();
if (!['ON','OFF','PING'].includes(cmd)) {
    msg.headers = { 'Content-Type':'application/json', 'Access-Control-Allow-Origin':'*' };
    msg.payload = { success:false, message:'Comando inválido' };
    return [null, msg];
}
const out = { topic: 'logistica/frio/comando', payload: cmd === 'PING' ? 'PING' : cmd };
let state = flow.get('dashboard_state') || {};
state.last_command = cmd;
state.last_updated = (new Date()).toISOString();
flow.set('dashboard_state', state);
// Reuse the original msg for the http response so req/res are preserved
msg.headers = { 'Content-Type':'application/json', 'Access-Control-Allow-Origin':'*' };
msg.payload = { success:true, message:`Comando ${cmd} enviado` };
return [out, msg];
